import Foundation

/// The zip reader and the inflate it depends on.
///
/// Self-contained on purpose: the vectors below are raw deflate streams produced
/// by zlib, so this runs anywhere without a corpus of files or an encoder. The
/// decoder itself was validated against Python's zlib over 33 cases and 1.1 MB
/// of input -- every compression level, every strategy, stored blocks, and the
/// 65535-byte stored-block boundary -- before these smaller cases were pinned
/// here. Validated against zlib rather than against its own encoder, because a
/// decoder checked against a matching encoder only proves the two agree.
@main
struct ZipArchiveTests {
    static var passed = 0
    static var failures: [String] = []

    static func check(_ name: String, _ got: [UInt8], _ want: [UInt8]) {
        if got == want {
            passed += 1
        } else {
            failures.append("\(name): got \(got.count) bytes, expected \(want.count)")
        }
    }

    static func expectThrows(_ name: String, _ body: () throws -> Void) {
        do {
            try body()
            failures.append("\(name): expected an error, got none")
        } catch {
            passed += 1
        }
    }

