            check("text", try Deflate.inflate(deflated_text), plain_text)
            check("sizes", try Deflate.inflate(deflated_sizes), plain_sizes)
            check("stored", try Deflate.inflate(deflated_stored), plain_stored)
            check("zeros", try Deflate.inflate(deflated_zeros), plain_zeros)
        } catch {
            failures.append("inflate threw unexpectedly: \(error)")
        }

        // ---- the zip reader ----------------------------------------------------

        // Names are normalised, because Windows-built archives use backslashes
        // where the zip spec wants forward slashes. Every addon measured on this
        // machine that came from Windows has them, and a reader that trusts the
        // stored form finds nothing under `synthDrivers/`.
        check("normalise backslash",
              [UInt8](Zip.normalise("synthDrivers\\_engine\\dll.dll").utf8),
              [UInt8](Zip.normalise("synthDrivers/_engine/dll.dll").utf8))
        check("normalise already forward",
              [UInt8](Zip.normalise("synthDrivers/dll.dll").utf8),
              [UInt8](Zip.normalise("synthDrivers/dll.dll").utf8))

        // Not a zip at all.
        expectThrows("random bytes are not a zip") {
            _ = try Zip.entries(Data([0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07]))
        }
        expectThrows("empty data is not a zip") {
            _ = try Zip.entries(Data())
        }
        expectThrows("text is not a zip") {
            _ = try Zip.entries(Data(repeating: 0x41, count: 1000))
        }

        // A file that is all zeros must not be mistaken for an archive.
        if (try? Zip.entries(Data(repeating: 0, count: 4096))) == nil {
            passed += 1
        } else {
            failures.append("4096 zero bytes were accepted as a zip")
        }

        // Inflate refuses a stream that is truncated, rather than returning
        // partial output that would be stored as a working voice.
        expectThrows("truncated deflate") {
            let full = Data(deflated_text)
            _ = try Deflate.inflate(full.prefix(full.count / 2))
        }

        // And refuses to expand past its limit, so a hostile archive is an error
        // rather than an allocation.
        expectThrows("output limit") {
            _ = try Deflate.inflate(Data(deflated_run), limit: 1024)
        }

        if failures.isEmpty {
            print("ZipArchiveTests: \(passed) checks passed")
        } else {
            print("ZipArchiveTests: \(passed) passed, \(failures.count) FAILED")
            for f in failures { print("  FAIL \(f)") }
        }
        exit(failures.isEmpty ? 0 : 1)
    }
}
